<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\UserFederatedIdentityRef;

final class UserFederatedIdentityRefUnitTest extends TestCase
{
    public function test(): void
    {
        $uid = 'uid';
        $ref = new UserFederatedIdentityRef(uid: $uid);
        $this->assertSame($uid, $ref->uid());
    }
}
